#ifndef ASTRO_REMOTE_PAGE_V137_H
#define ASTRO_REMOTE_PAGE_V137_H

static const char *remote_page_v137=
"<!doctype html><html lang='pt-BR'><head>"
"<meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1,viewport-fit=cover'>"
"<title>Astro - Remote Service</title>"
"<style>"
"*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:#090d13;color:#edf4ff;font-family:Arial,sans-serif}"
"body{background:radial-gradient(circle at 50% 0,#142238 0,#090d13 42%,#06080c 100%)}"
"header{height:64px;display:flex;align-items:center;gap:12px;padding:0 18px;border-bottom:1px solid #263447;background:rgba(9,13,19,.94)}"
"header a{color:#c8d6e8;text-decoration:none;font-weight:800}.brand{font-weight:900;letter-spacing:.09em}.spacer{flex:1}"
".pill{padding:6px 9px;border:1px solid #34465f;border-radius:999px;color:#9eb1c8;font-size:12px}.pill.on{color:#9ee7bb;border-color:#315841}.pill.bad{color:#ffb6bf;border-color:#61323b}"
"main{padding:22px;max-width:1180px;margin:0 auto}.grid{display:grid;grid-template-columns:minmax(0,1fr) 360px;gap:16px}"
".screen{aspect-ratio:16/9;background:#020304;border:1px solid #28394f;border-radius:16px;display:grid;place-items:center;overflow:hidden;box-shadow:0 28px 90px rgba(0,0,0,.38)}"
".screen-inner{text-align:center;padding:26px}.screen h2{margin:0 0 8px}.screen p{margin:0;color:#7f93aa;line-height:1.5}.dot{width:10px;height:10px;border-radius:50%;background:#4d627d;margin:0 auto 14px;box-shadow:0 0 22px rgba(91,129,177,.45)}"
".panel{border:1px solid #29394e;background:#0f1620;border-radius:16px;padding:18px;height:max-content}.panel h3{margin:0 0 16px}.row{display:flex;justify-content:space-between;gap:12px;padding:9px 0;border-bottom:1px solid #202c3b;font-size:13px}.row span:first-child{color:#8397af}.row span:last-child{text-align:right;font-weight:700;word-break:break-word}"
"button{width:100%;margin-top:12px;padding:11px;border-radius:9px;border:1px solid #405676;background:#162235;color:#eaf2ff;font-weight:800;cursor:pointer}.primary{background:#d8e7f8;color:#091019;border-color:#d8e7f8}.danger{background:#261519;border-color:#61323b;color:#ffb6bf}.secondary{background:#151c26;color:#c9d8e9;border-color:#34465f}.enable{background:#17291e;border-color:#355d43;color:#a7e9ba}button:disabled{opacity:.5;cursor:default}"
".note{margin-top:14px;color:#71859d;font-size:12px;line-height:1.5}.error{margin-top:12px;color:#ff9da9;font-size:12px;display:none}"
"@media(max-width:820px){.grid{grid-template-columns:1fr}main{padding:12px}header{padding:0 12px}.brand{font-size:13px}}"
"</style></head><body>"
"<header><a href='/'>← Astro</a><span class='brand'>REMOTE SERVICE</span><span id='servicePill' class='pill'>WORKER</span><span class='spacer'></span><span id='phasePill' class='pill'>IDLE</span></header>"
"<main><div class='grid'><section class='screen'><div class='screen-inner'><div class='dot'></div><h2 id='screenTitle'>Remote interno pronto</h2><p id='screenText'>Esta interface é servida pelo astrorem em localhost e passa pelo proxy do Astro.</p></div></section>"
"<aside class='panel'><h3>Astro Remote</h3>"
"<div class='row'><span>Worker</span><span id='worker'>...</span></div>"
"<div class='row'><span>Canal interno</span><span id='channel'>127.0.0.1:45822</span></div>"
"<div class='row'><span>Health</span><span id='health'>...</span></div>"
"<div class='row'><span>Uso remoto</span><span id='rpEnabled'>...</span></div>"
"<div class='row'><span>Servidor RP 9295</span><span id='rpPort'>...</span></div>"
"<div class='row'><span>Protocolo RP</span><span id='rpVersion'>NÃO TESTADO</span></div>"
"<div class='row'><span>HTTP handshake</span><span id='rpHttp'>NÃO TESTADO</span></div>"
"<div class='row'><span>Pareamento</span><span id='pairing'>NÃO TESTADO</span></div>"
"<div class='row'><span>Sessão</span><span id='session'>...</span></div>"
"<div class='row'><span>Vídeo</span><span id='video'>...</span></div>"
"<div class='row'><span>Controle</span><span id='control'>...</span></div>"
"<div class='row'><span>Tempo</span><span id='uptime'>...</span></div>"
"<button id='enable' class='enable'>HABILITAR USO REMOTO</button><button id='start' class='primary'>TESTAR HANDSHAKE / INICIAR</button><button id='stop' class='danger'>ENCERRAR SESSÃO</button><button id='restart' class='secondary'>REINICIAR SERVIÇO INTERNO</button>"
"<div id='error' class='error'></div>"
"<div class='note'>A 45822 continua restrita a localhost. Este build testa diretamente o endpoint de sessão do Remote Play em /sie/ps5/rp/sess/init. O teste usa uma chave propositalmente inválida: ele descobre protocolo e estado de autenticação sem tentar capturar vídeo ainda.</div>"
"</aside></div></main>"
"<script>"
"const $=id=>document.getElementById(id);let busy=false;"
"function fmt(n){n=Number(n)||0;const h=Math.floor(n/3600),m=Math.floor((n%3600)/60),s=n%60;return (h?h+'h ':'')+(m?m+'m ':'')+s+'s'}"
"function lock(v){busy=v;$('enable').disabled=v;$('start').disabled=v;$('stop').disabled=v;$('restart').disabled=v}"
"function showError(t){$('error').textContent=t||'';$('error').style.display=t?'block':'none'}"
"function hexReason(n){n=Number(n)||0;return n?'0x'+n.toString(16).padStart(8,'0').toUpperCase():'-'}"
"async function status(){try{const rs=await Promise.all([fetch('/api/remote/status',{cache:'no-store'}),fetch('/service/remote/status',{cache:'no-store'})]);const j=await rs[0].json(),w=await rs[1].json();if(!rs[0].ok)throw new Error(j.error||('HTTP '+rs[0].status));if(!rs[1].ok)throw new Error(w.error||('worker HTTP '+rs[1].status));const online=!!j.service_online,stuck=!!j.worker_stuck,rp=!!j.remoteplay_enabled,rpp=!!j.remoteplay_tcp_9295,proto=!!w.protocol_ready,auth=!!w.session_authenticated,pair=!!w.pairing_required;$('worker').textContent=j.worker_pid?('astrorem PID '+j.worker_pid):'OFFLINE';$('channel').textContent=(j.internal_bind||'127.0.0.1')+':'+(j.internal_port||45822);$('health').textContent=stuck?'TRAVADO':(online?'ONLINE':'OFFLINE');$('rpEnabled').textContent=rp?'HABILITADO':'DESATIVADO';$('rpPort').textContent=rpp?'RESPONDENDO':'SEM RESPOSTA';$('rpVersion').textContent=proto?(w.rp_version||'SEM HEADER'):'NÃO TESTADO';$('rpHttp').textContent=proto?('HTTP '+w.rp_http_status+' · '+hexReason(w.rp_application_reason)):'NÃO TESTADO';$('pairing').textContent=auth?'AUTENTICADO':(pair?'NECESSÁRIO':'NÃO TESTADO');$('enable').style.display=rp?'none':'block';$('session').textContent=auth?'ATIVA':(j.session_active?'PREPARAÇÃO':'PARADA');$('video').textContent=j.video_ready?'PRONTO':(pair?'AGUARDANDO PAREAMENTO':'AGUARDANDO PIPELINE');$('control').textContent=j.control_ready?'PRONTO':(pair?'AGUARDANDO PAREAMENTO':'AGUARDANDO');$('uptime').textContent=fmt(j.session_uptime_seconds);$('servicePill').textContent=stuck?'WORKER TRAVADO':(online?'WORKER ONLINE':'WORKER OFFLINE');$('servicePill').className='pill '+(stuck?'bad':(online?'on':''));$('phasePill').textContent=(w.phase||j.phase||'idle').replaceAll('_',' ').toUpperCase();if(stuck){$('screenTitle').textContent='Remote interno travado';$('screenText').textContent='O Astro continua vivo na 45821. Reinicie somente o processo astrorem.'}else if(!rp){$('screenTitle').textContent='Uso remoto desativado';$('screenText').textContent='Habilite o Remote Play do PS5 para usar a captura e codificação nativas.'}else if(pair){$('screenTitle').textContent='Protocolo Remote Play respondeu';$('screenText').textContent='O endpoint de sessão respondeu, mas o Astro ainda não possui as credenciais de pareamento. Próxima etapa: registrar o astrorem como cliente local e guardar RegistKey + Morning.'}else if(auth){$('screenTitle').textContent='Handshake autenticado';$('screenText').textContent='Sessão autenticada. Próximo estágio: CTRL, Senkusha/Takion e primeiro pacote de vídeo.'}else if(proto){$('screenTitle').textContent='Protocolo Remote Play detectado';$('screenText').textContent='O PS5 respondeu ao endpoint de sessão. Os detalhes do handshake estão no painel.'}else if(online){$('screenTitle').textContent='Remote interno pronto';$('screenText').textContent='Clique em testar handshake para consultar o endpoint nativo de sessão do PS5.'}else{$('screenTitle').textContent='Remote interno indisponível';$('screenText').textContent='O Astro continua acessível na 45821, mas o worker interno não respondeu.'}showError('')}catch(e){$('health').textContent='SEM RESPOSTA';showError(String(e.message||e))}}"
"async function act(path){if(busy)return;lock(true);showError('');try{const r=await fetch(path,{method:'POST'});const j=await r.json();if(!r.ok){const rc=(typeof j.rc==='undefined')?'?':j.rc;throw new Error((j.error||'Falha')+' rc='+rc+' phase='+(j.phase||'?'))}await status()}catch(e){showError(String(e.message||e));await status()}finally{lock(false)}}"
"$('enable').onclick=()=>act('/api/remote/enable');$('start').onclick=()=>act('/api/remote/start');$('stop').onclick=()=>act('/api/remote/stop');$('restart').onclick=()=>act('/api/remote/restart');status();setInterval(()=>{if(!busy)status()},1500);"
"</script></body></html>";

#endif
